-- Prepared for homologation; do not apply automatically.
create or replace function public.sma_signal_center_is_admin(p_email text) returns boolean language sql security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.clientes where lower(email)=lower(p_email) and (upper(coalesce(tipo_usuario,''))='ADMIN' or lower(coalesce(plano,''))='admin/base')); $$;
create or replace function public.sma_signal_center_get(p_admin_email text) returns public.sma_signal_center_config language plpgsql security definer set search_path=public,pg_temp as $$ declare r public.sma_signal_center_config; begin if not public.sma_signal_center_is_admin(p_admin_email) then raise exception 'admin_required'; end if; select * into r from public.sma_signal_center_config where id=true; if r.id is null then insert into public.sma_signal_center_config(auto_assets,manual_assets,timeframe,updated_by) values(array['BTCUSDT','ETHUSDT'],array['BTCUSDT','ETHUSDT'],'5m',p_admin_email) returning * into r; end if; return r; end; $$;
create or replace function public.sma_signal_center_set(p_admin_email text,p_auto_assets text[],p_manual_assets text[],p_timeframe text,p_auto_enabled boolean,p_emergency_stop boolean) returns public.sma_signal_center_config language plpgsql security definer set search_path=public,pg_temp as $$ declare r public.sma_signal_center_config; begin if not public.sma_signal_center_is_admin(p_admin_email) then raise exception 'admin_required'; end if; if coalesce(array_length(p_auto_assets,1),0)<>2 or coalesce(array_length(p_manual_assets,1),0)<>2 or p_auto_assets[1]=p_auto_assets[2] or p_manual_assets[1]=p_manual_assets[2] then raise exception 'exactly_two_assets_required'; end if; insert into public.sma_signal_center_config(id,auto_assets,manual_assets,timeframe,auto_enabled,emergency_stop,updated_by) values(true,p_auto_assets,p_manual_assets,p_timeframe,p_auto_enabled,p_emergency_stop,p_admin_email) on conflict(id) do update set auto_assets=excluded.auto_assets,manual_assets=excluded.manual_assets,timeframe=excluded.timeframe,auto_enabled=excluded.auto_enabled,emergency_stop=excluded.emergency_stop,updated_by=excluded.updated_by,updated_at=now() returning * into r; return r; end; $$;
create or replace function public.sma_signal_center_history(p_admin_email text,p_limit int default 100) returns setof public.sma_signal_center_audit language sql security definer set search_path=public,pg_temp as $$ select * from public.sma_signal_center_audit where public.sma_signal_center_is_admin(p_admin_email) order by created_at desc limit least(greatest(p_limit,1),500); $$;
revoke all on function public.sma_signal_center_is_admin(text),public.sma_signal_center_get(text),public.sma_signal_center_set(text,text[],text[],text,boolean,boolean),public.sma_signal_center_history(text,int) from public,anon,authenticated;
grant execute on function public.sma_signal_center_is_admin(text),public.sma_signal_center_get(text),public.sma_signal_center_set(text,text[],text[],text,boolean,boolean),public.sma_signal_center_history(text,int) to service_role;
